L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "Eine optische Neugestaltung der Blizzard Taschen mit intuitiver Sortierung."
L["A blank bar to build from scratch."] = "Eine leere Leiste zum Erstellen von Grund auf."
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Ein helles, minimalistisches Layout mit sauberer Ästhetik. Entwickelt für jede Rolle mit übersichtlichen Informationen und einem ruhigen, fokussierten Gefühl."
L["a Buff bar"] = "eine Stärkungszauber Leiste"
L["a buff/aura"] = "ein Stärkungszauber/eine Aura"
L["A CDM replacement focused on performance, customizations and alerts."] = "Ein CDM-Ersatz mit Fokus auf Leistung, Anpassungsmöglichkeiten und Warnungen."
L["A clean minimal setup"] = "Ein sauberes, minimales Setup"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Ein aufgeräumtes, luftiges Layout mit übersichtlichen Informationen auf einen Blick. Angenehm für lange Sessions in allen Inhalten."
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "Eine aufgeräumte, aktualisierte Neugestaltung der Blizzard Questverfolgung."
L["a Cooldown or Utility bar"] = "eine Abklingzeiten- oder Nützliches Leiste"
L["a cooldown"] = "eine Abklingzeit"
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Ein dunkles, elegantes Heiler Setup, aufgebaut um Schlachtzugsfenster und übersichtliche Informationen, um Dein Team im Blick zu behalten."
L["a Dispel Glow Style"] = "ein Bann Leuchtstil"
L["A Horizontally Growing Anchor Target"] = "Ein horizontal wachsendes Ankerziel"
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Ein helles Heiler Setup, aufgebaut um Schlachtzugsfenster und klare Lesbarkeit, das die Gesundheit Deines Teams stets im Fokus hält."
L["a Mail Position corner"] = "eine Post Positionsecke"
L["A modern friends list with built-in organization tools."] = "Eine moderne Freundesliste mit integrierten Verwaltungswerkzeugen."
L["A new age minimap with clean styling and square layout options."] = "Eine moderne Minikarte mit sauberem Design und quadratischen Layout Optionen."
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "Ein Profil mit dem Namen \"%1$s\" existiert bereits. Bitte wähle einen anderen Namen."
L["A quick view of every font setting in one place."] = "Eine schnelle Übersicht aller Schriftarteinstellungen an einem Ort."
L["A quick view of every texture setting in one place."] = "Eine schnelle Übersicht aller Textureinstellungen an einem Ort."
L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Ein Schlachtzugs Bedienfeld mit Bereitschaftsabfrage, Pull Timer und Schlachtzugsmarkern. Im Schlachtzug wird es nur angezeigt, wenn Du Leiter oder Assistent bist; in einer Gruppe wird es immer angezeigt."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Ein dezent schattiertes Layout, das den Bildschirm übersichtlich hält. Informationen erscheinen genau dann, wenn Du sie brauchst."
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Eine Spezialisierungs Überschreibung besitzt diese Einstellung, daher wird dieser bedingte Wert außerhalb einer Bearbeitungssitzung nie angewendet. Entferne die Spezialisierungs-Überschreibung, um ihn zuzulassen."
L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "Eine eigenständige Zauberleiste für diese Einheit, die im Freigabemodus frei platziert werden kann. Läuft parallel zu den Zauberleisten der Einheitenfenster."
