L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Fügt bei Berufslehrern eine Taste 'Alle erlernen' hinzu, um alle verfügbaren Fertigkeiten mit einem Klick zu erlernen."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "Fügt dem Charakterfenster eine Taste hinzu, die den Aufwertungsrechner öffnet und schließt."
L["Adds a glowing, pulsating border around the Accept button of resurrection popups so a pending resurrect is hard to miss. Follows the Element & Text Color setting. Applies instantly, no reload needed."] = "Fügt beim Wiederbelebungs-Popup einen leuchtenden, pulsierenden Rahmen um die Annahme Taste hinzu. Übernimmt die Einstellung der Element- & Textfarbe. Gilt sofort ohne Neuladen."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Fügt einen Anker für Blizzards oberen Ereignistext und Widgets (Szenario-, Ereignis- and Bossleisten) hinzu."
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "Fügt Deinem Spielerfenster einen Schattenrahmen hinzu, wenn Du als Nicht-Tank Bedrohung hast. Nur in Dungeons, Schlachtzügen und Tiefen aktiv."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Fügt ein rotes Leuchten um die Namensplakette hinzu, solange die 'Pufferzone' Farbe aktiv ist."
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Fügt am linken Rand von Beutebenachrichtigungen einen Streifen in der Qualitätsfarbe des Gegenstands hinzu."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Fügt eine Zielzeile hinzu, die anzeigt, wen der anvisierte Spieler oder NSC im Ziel hat (grün, wenn Du es bist)."
L["Adds Bonus Roll, Group Loot, and Alert Toast movers to Unlock Mode."] = "Fügt Anker für Bonuswurf, Gruppenbeute und Benachrichtigungen zum Freigabemodus hinzu."
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "Fügt das Reittier eines Spielers seinem Tooltip hinzu (mit grünem Haken, wenn Du es besitzt, oder rotem X, wenn nicht)."
L["Adds timestamps to system messages, loot, achievements, and addon messages, not just player chat."] = "Fügt Systemnachrichten, Beute, Erfolgen und Addon Nachrichten Zeitstempel hinzu, nicht nur dem Spieler-Chat."
