L["Another override group already provides the custom Buff Manager for your current spec."] = "Eine andere Überschreibungsgruppe stellt bereits den eigenen Stärkungszauber Manager für Deine aktuelle Spezialisierung bereit."
L["Another override group already provides the custom Debuff Manager for your current spec."] = "Eine andere Überschreibungsgruppe stellt bereits den eigenen Schwächungszauber Manager für Deine aktuelle Spezialisierung bereit."
L["Any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it."] = "Jeder Schwächungszauber mit einem Banntyp (Magie, Fluch, Krankheit, Gift, Blutung), selbst wenn Du ihn nicht entfernen kannst."
L["Any setting you change now applies only to this group's specs."] = "Jede Einstellung, die Du jetzt änderst, gilt nur für die Spezialisierungen dieser Gruppe."
L["Any setting you change now applies only while this conditional is active."] = "Jede Einstellung, die Du jetzt änderst, gilt nur, solange diese Bedingung aktiv ist."
L["Appends an item's max stack count on tooltip."] = "Fügt die maximale Stapelgröße eines Gegenstands im Tooltip hinzu."
L["Appends the cast target to the spell name (Spell Name - Target), class colored, and disables the separate Spell Target display."] = "Fügt das Zauberziel an den Zaubernamen an (Zaubername - Ziel), in Klassenfarbe eingefärbt, und deaktiviert die separate Zauberziel Anzeige."
L["Appends the spell or item ID to tooltips. The same setting as Global Settings > Developer."] = "Fügt den Tooltips die Zauber- oder Gegenstands-ID hinzu. Entspricht der Einstellung in Globale Einstellungen > Entwickler."
L["Appends your latency in milliseconds to the cast timer, e.g. 1.8 (42ms)."] = "Fügt Deine Latenz in Millisekunden an den Zaubertimer an, z. B. 1,8 (42ms)."
L["Applies EllesmereUI theme styling to the inspect sheet window."] = "Wendet das EllesmereUI Design auf das Instandhaltungs-/Betrachten Fenster an."
L["Applies one text size to every chat window, saved with your profile. Individual windows can still be adjusted from their tab's right-click menu until the next login re-applies the profile size."] = "Wendet eine einheitliche Textgröße auf jedes Chatfenster an, gespeichert in Deinem Profil. Einzelne Fenster können weiterhin über das Rechtsklick-Menü ihres Tabs angepasst werden, bis das Neuanmelden die Profilgröße wieder anwendet."
L["Applies your Global Font to Blizzard's default game text (menus, tooltips, quest log, character panes, and more). Requires a UI reload."] = "Wendet Deine globale Schriftart auf Blizzards Standard Spieltext an (Menüs, Tooltips, Questlog, Charakterfenster und mehr). Erfordert ein Neuladen des UI."
