L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "Automatisch richtet sich nach dem Zonennamen. Manuell hält den Block auf fester Breite und kürzt längere Namen ab, sodass benachbarte Blöcke nicht verschoben werden."
L["Automatic shows XP while leveling and reputation at max level."] = "Automatisch zeigt Erfahrung beim Leveln und Ruf auf der Höchststufe an."
L["Automatic"] = "Automatisch"
L["Automatically add a bar to this group for every spell in Blizzard's Tracked Bars section, now and whenever a new one appears."] = "Fügt dieser Gruppe automatisch eine Leiste für jeden Zauber in Blizzards Bereich für verfolgte Leisten hinzu, jetzt und sobald ein neuer erscheint."
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Blendet die Fanfaren Benachrichtigung für 'Neues Reittier/Haustier/Spielzeug' automatisch aus, wenn Du eines erhältst."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the frame cap with hotkey picks."] = "Dupliziert die Tanks des Schlachtzugs automatisch in die Extra Fenstergruppe. Teilt sich die maximale Fensteranzahl mit Hotkey Auswahlen."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Aktiviert automatisch den Filter 'Nur aktuelle Erweiterung', sobald Du das Auktionshaus öffnest."
L["Automatically inserts your key into the Font of Power."] = "Setzt Deinen Schlüsselstein automatisch in den Quell der Macht ein."
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "Öffnet und schließt den Aufwertungsrechner automatisch, wenn das Charakterfenster geöffnet oder geschlossen wird."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Öffnet automatisch Taschen, Kisten und Pakete in Deinem Inventar, sobald sie hinzugefügt werden.\n\nBehälter aus dem Postkasten werden zurückgehalten, bis Du den Postkasten schließt."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "Öffnet den Aufwertungsrechner automatisch, wenn das Fenster des Wappen-Aufwertungshändlers geöffnet wird."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "Entfernt automatisch kosmetische Verwandlungen (Berufsausrüstung, Feiertagskostüme, Spielzeuge, Verbrauchsgüter). Nutze das Zahnrad, um auszuwählen, welche Verwandlungen entfernt werden. Während des Kampfes angewendete Verwandlungen werden nach Kampfende entfernt."
L["Automatically repair all gear when visiting a repair vendor."] = "Repariert automatisch die gesamte Ausrüstung beim Besuch eines Reparaturhändlers."
L["Automatically sell all junk items when visiting a vendor."] = "Verkauft beim Besuch eines Händlers automatisch allen Müll."
L["Automatically Skip If Possible"] = "Automatisch überspringen, falls möglich"
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "Startet und stoppt die Kampfaufzeichnung automatisch beim Betreten oder Verlassen einer aufzeichenbaren Instanz."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Tippt automatisch 'LÖSCHEN' ein, wenn Du einen wertvollen Gegenstand wegwirfst. Ermöglicht außerdem das Bestätigen per Eingabetaste."
L["Automatically zoom back out to maximum distance after this many seconds of no manual zoom change. 0 disables the reset."] = "Zoomt nach dieser Anzahl an Sekunden ohne manuelle Änderung automatisch wieder auf die maximale Distanz heraus. 0 deaktiviert das Zurücksetzen."
L["Available only when Anchor to Windows is set to Free Move."] = "Nur verfügbar, wenn 'An Fenstern verankern' auf 'Frei bewegen' eingestellt ist."
