L["Collapse subgroups that have no members so the remaining groups close ranks. For example, if only groups 1, 2, 3 and 6 have players, they show with no gaps instead of leaving empty space where groups 4 and 5 would be. Real raid frames only."] = "Klappt Untergruppen ohne Mitglieder ein, sodass verbleibende Gruppen aufrücken. Beispiel: Haben nur die Gruppen 1, 2, 3 und 6 Spieler, werden sie ohne Lücken angezeigt. Nur für echte Schlachtzugsfenster."
