L["EllesmereUI Basics has been split into separate addons. Since you had Basics disabled, Minimap, Friends, and Quest Tracker have been disabled to match. A reload is required to apply this change."] = "EllesmereUI Basics wurde in separate Addons aufgeteilt. Da Du Basics deaktiviert hattest, wurden Minikarte, Freunde und Quest Verfolgung entsprechend deaktiviert. Ein Neuladen ist erforderlich, um diese Änderung zu übernehmen."
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI konnte diese Änderung nicht in Deinem Bearbeitungsmodus Layout speichern, daher muss sie manuell vorgenommen werden. Der Abklingzeiten-Manager muss währenddessen ausgeschaltet sein, da er die AbklingzeitenAnzeigen von Blizzard ausblendet und eine ausgeblendete Anzeige im Bearbeitungsmodus nicht ausgewählt werden kann.\n\n"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI konnte diese Änderung nicht in Deinem Bearbeitungsmodus Layout speichern, daher muss sie manuell vorgenommen werden. Der Abklingzeiten-Manager muss währenddessen ausgeschaltet sein, da er die AbklingzeitenAnzeigen von Blizzard ausblendet und eine ausgeblendete Anzeige im Bearbeitungsmodus nicht ausgewählt werden kann.\n\n1. Deaktiviere den EllesmereUI Abklingzeiten-Manager (Taste unten).\n2. Öffne den Bearbeitungsmodus über das Spielmenü.\n3. Wähle jede AbklingzeitenAnzeige aus und stelle die Sichtbarkeit auf 'Immer'.\n4. Aktiviere bei 'Verfolgte Stärkungszauber' und 'Verfolgte Leisten' die Option 'Bei Inaktivität ausblenden'.\n5. Speichere das Layout und verlasse den Bearbeitungsmodus.\n6. Aktiviere den EllesmereUI Abklingzeiten-Manager wieder."
L["EllesmereUI Default"] = "EllesmereUI-Standard"
L["EllesmereUI has updated your CDM Edit Mode settings to ensure cooldown tracking works correctly.\n\nA UI reload is required for the changes to take effect."] = "EllesmereUI hat Deine Bearbeitungsmodus Einstellungen für den CDM aktualisiert, um sicherzustellen, dass die Abklingzeiten Verfolgung korrekt funktioniert.\n\nEin Neuladen des UI ist erforderlich, damit die Änderungen wirksam werden."
