L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "EllesmereUI WonderBar wurde in EllesmereUI DataBars umbenannt. Das alte WonderBar Addon ist noch installiert und beide erstellen dieselbe Leiste. Bitte deaktiviere oder lösche das EllesmereUIWonderBar Addon."
