L["Flash the cast bar and show \"Interrupted\" for a moment when the cast is interrupted."] = "Lässt die Zauberleiste aufblitzen und zeigt kurz \"Unterbrochen\" an, wenn der Zauber unterbrochen wird."
L["Flash the enemy's cast bar and show \"Interrupted\" for a moment when their cast is interrupted. Use the swatch to change the flash colour."] = "Lässt die zaubernde Leiste des Gegners aufblitzen und zeigt kurz \"Unterbrochen\" an, wenn dessen Zauber unterbrochen wird. Nutze das Farbfeld, um die Blitzfarbe zu ändern."
L["Flash"] = "Aufblitzen"
L["Flashes a banner whenever a tracked mobility spell's cooldown is proc-reset. Use Unlock Mode to reposition/resize."] = "Lässt ein Banner aufblitzen, wann immer die Abklingzeit eines verfolgten Bewegungszaubers durch einen Proc zurückgesetzt wird. Nutze den Freigabemodus zum Neupositionieren/Skalieren."
L["Flashes a warning on screen when any equipped item drops below the configured durability threshold. Only triggers out of combat."] = "Lässt eine Warnung auf dem Bildschirm aufblitzen, wenn die Haltbarkeit eines ausgerüsteten Gegenstands unter den konfigurierten Schwellenwert fällt. Wird nur außer Kampf ausgelöst."
L["Flashes LOW MANA during an out-of-combat raid ready check while you are a healer under 80% mana."] = "Lässt 'WENIG MANA' während einer Bereitschaftsabfrage außer Kampf aufblitzen, wenn Du ein Heiler mit weniger als 80% Mana bist."
