L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, %sclick here|r"] = "Bietet für das Spielerfenster eine einfache Mini Zauberleiste unter dem Spielerfenster. Um die Haupt Zauberleiste des Spielers zu bearbeiten, %sklicke hier|r"
L["For tabs outside the chat panel, uses the chat panel's border style and color instead of separate tab border settings."] = "Nutzt für Reiter außerhalb des Chatfensters den Rahmenstil und die Farbe des Chatfensters anstelle separater Rahmen Einstellungen für Reiter."
