L["Force-hide Blizzard's Assisted Combat Highlight (rotation helper glow) on all CDM bars, even if enabled in Blizzard's Combat settings."] = "Erzwingt das Ausblenden von Blizzards Hervorhebung für unterstützten Kampf (Rotationshilfe Leuchten) auf allen CDM Leisten, selbst wenn in Blizzards Kampfeinstellungen aktiviert."
L["Forces a crisp outline on icon text (stack counts, durations, keybinds). Uncheck a module to make its icon text follow the Outline Mode setting above instead."] = "Erzwingt eine scharfe Kontur auf Symboltexten (Stapelanzahlen, Dauer, Tastenbelegungen). Deaktiviere ein Modul, damit dessen Symboltext stattdessen der oben stehenden Einstellung für den Konturmodus folgt."
