L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Blendet feindliche Namensplaketten aus, wenn Du außer Kampf bist; sie kehren zu Beginn des Kampfes zurück. Steuert dieselbe Spieleinstellung wie die Tastenbelegung 'Feindliche Namensplaketten anzeigen'."
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Blendet Einträge aus, die dieser Charakter nicht nutzen kann: Spezialisierungen und Zauber anderer Klassen sowie Makros, die dieser Charakter nicht besitzt. Ein gemeinsames Menü passt so für jeden Charakter. Der Menü-Editor zeigt immer alle Einträge an."
