L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Blendet die Gesundheitsleisten freundlicher Spieler aus, sodass nur ihre Namen sichtbar sind.\n\nErfordert, dass 'Vereinfachte freundliche Namensplaketten' in Blizzards Namensplaketten Einstellungen deaktiviert ist (Esc > Optionen > Namensplaketten)."
