L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "Blendet die kurze GCD-Wischtextur aus, die beim Wirken eines beliebigen Zaubers aufblitzt. Die eigentliche Abklingzeit-Wischtextur der Fähigkeit wird weiterhin angezeigt."
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Blendet die Aufladungszahl auf Aktionsknöpfen aus, wenn sie 0 erreicht, anstatt eine 0 anzuzeigen. Die Zahl kehrt zurück, sobald eine Aufladung oder ein Gegenstand wieder verfügbar ist."
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "Blendet die Aufladungszahl aus, während ein Zauber keine Aufladungen mehr hat, anstatt eine 0 anzuzeigen. Die Zahl kehrt zurück, sobald eine Aufladung wieder verfügbar ist."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Blendet den Namenstext des Gegners aus, solange die Zauberleiste dieser Namensplakette sichtbar ist."
L["Hide the icon texture, border, and duration swipe, leaving only the stack count. Forces icon opacity, border, and duration swipe off."] = "Blendet Symboltextur, Rahmen und Dauer-Wischtextur aus, sodass nur die Stapelanzahl übrig bleibt. Schaltet Symboldeckkraft, Rahmen und Dauer-Wischtextur erzwungen aus."
L["Hide the preview"] = "Vorschau ausblenden"
L["Hide the randomize (dice) button in the OneBag view."] = "Blendet die Zufallstaste (Würfel) in der Einzeltasche Ansicht aus."
L["Hide the warning text at the top of the OneBag and MultiBag views."] = "Blendet den Warntext oben in der Einzeltasche- und Mehrfachtasche Ansicht aus."
L["Hide these instead of showing them"] = "Diese ausblenden, anstatt sie anzuzeigen"
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Blendet Symbolgrafik, Abklingzeit-Wischtextur, Wiederaufladekante und Abklingzeittext dieser Leiste aus, sodass nur die Aufladungs- oder Stapelanzahl übrig bleibt."
L["Hide this bar's icons and show only the duration text."] = "Blendet die Symbole dieser Leiste aus und zeigt nur den Dauertext an."
