L["Hide without Target"] = "Ohne Ziel ausblenden"
L["Hides Blizzard's own micro menu while any bar has this on."] = "Blendet Blizzards eigenes Mikromenü aus, solange irgendeine Leiste dies aktiviert hat."
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Blendet Blizzards Tutorial-UI aus: die gelben Hilfe-Sprechblasen und die leuchtenden (i) -Hilfetasten in Zauberbuch, Talenten, Karte, Sammlungen und anderen Fenstern."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Blendet die meisten roten Fehlermeldungen aus (wie 'Nicht genug Wut' oder 'Fähigkeit ist noch nicht bereit'). Wichtige Fehler wie eine volle Taschen- oder Questlog Kapazität werden weiterhin angezeigt."
L["Hides Pinned Items. Re-show in settings."] = "Blendet angepinnte Gegenstände aus. In den Einstellungen wieder anzeigen."
L["Hides Recent Items. Re-show in settings."] = "Blendet kürzliche Gegenstände aus. In den Einstellungen wieder anzeigen."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Blendet die 'Screenshot gespeichert'-Benachrichtigung aus, die nach dem Erstellen eines Screenshots auf dem Bildschirm erscheint."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Blendet die Taste 'Kategorie hinzufügen' am unteren Rand der Taschen-Seitenleiste aus."
L["Hides the collapsed Blizzard party/raid sidebar panel on the side of the screen."] = "Blendet das eingeklappte Blizzard Gruppen-/Schlachtzug-Seitenleistenfenster am Bildschirmrand aus."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Blendet die EllesmereUI Taste im Escape-/Pausemenü des Spiels aus."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Blendet das große NSC Dialog Popup aus, das während Quests und Dungeons erscheint."
L["Hides the loot window movers in Unlock Mode while keeping their saved positions applied."] = "Blendet die Mover des Beutefensters im Freigabemodus aus, während ihre gespeicherten Positionen angewendet bleiben."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Blendet das Lua-Fehler Popup aus. Dieselbe Einstellung wie 'Globale Einstellungen > Entwickler'."
L["Hides the master header and its minimize button at the top of the tracker. When shown, it's skinned to match the section headers below it (Quests, Achievements, ...)."] = "Blendet die Hauptkopfzeile und deren Minimieren Taste oben in der Verfolgung aus. Wenn angezeigt, wird sie optisch an die darunter liegenden Abschnittskopfzeilen (Quests, Erfolge, ...) angepasst."
L["Hides the rank number (1. 2. 3.) before each player name."] = "Blendet die Rangnummer (1. 2. 3.) vor jedem Spielernamen aus."
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Blendet das Bereitschaftsabfrage Symbol über der Abfrage aus, sodass nur die Frage und die Ja-/Nein Tasten übrig bleiben. Gilt, während der Skin für die Bereitschaftsabfrage aktiviert ist."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Blendet den Skalierungsgriff am Haupt Chatfenster aus, um ein versehentliches Ändern der Größe zu verhindern."
L["Hides the sync icons on the sidebar module list."] = "Blendet die Synchronisationssymbole in der Seitenleisten Modulliste aus."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Blendet den Mover für den Ereignistext der oberen Leiste im Freigabemodus aus, während dessen gespeicherte Position angewendet bleibt."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Blendet die Freigabemodus Taste im Escape-/Pausemenü des Spiels aus. Du kannst den Freigabemodus weiterhin über das EUI Optionsfenster umschalten."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Blendet dieses Element aus, während Du auf einem Himmelsreiten Reittier (gleitfähig) sitzt, bei dem Blizzard seine SchwungAnzeige einblendet."
