L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Wie zusätzliche Spalten wachsen, wenn die zweite Spalte erscheint oder verschwindet. 'Nach rechts wachsen' hält die linke Spalte an Ort und Stelle, 'Nach links wachsen' hält die rechte Spalte an Ort und Stelle, 'Zentriert wachsen' hält die Leiste zentriert."
L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Wie zusätzliche Zeilen wachsen, wenn die zweite Zeile erscheint oder verschwindet. 'Nach unten wachsen' hält die obere Zeile an Ort und Stelle, 'Nach oben wachsen' hält die untere Zeile an Ort und Stelle, 'Zentriert wachsen' hält die Leiste zentriert."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Wie weit sich ein Schachtelungsbereich entlang des Bogens ausbreiten darf. 'Enthalten' hält ihn frei von benachbarten Schachtelungen, sodass nie zwei übereinander gezeichnet werden. 'Überlaufend' erlaubt die Nutzung der gesamten maximalen Schachtelungsspanne."
L["How far along the arc a nest may spread its entries."] = "Wie weit sich ein Submenü entlang des Bogens ausbreiten darf."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Wie viele Einträge eine Rasterzeile fasst. 1 stapelt sie in eine einzelne Spalte; %1$s -- die maximale Platzenzahl für ein Aktionsmenü -- ordnet sie in einer einzigen Zeile an."
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "Wie viele Symbole auf der Basiszeile angezeigt werden sollen (die Zeile, die sich zuerst füllt und die das Zeilenwachstum an Ort und Stelle hält). Der Rest wandert in die zweite Zeile."
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Wie viel oben und unten vom Symbol zugeschnitten wird, als Prozentsatz pro Seite. 10% entspricht dem klassischen zugeschnittenen Aussehen."
L["How precise the coordinates read. More decimals make the block wider."] = "Wie präzise die Koordinaten abgelesen werden. Mehr Nachkommastellen machen den Block breiter."
L["How wide the block stays, whatever the zone is called."] = "Wie breit der Block bleibt, unabhängig vom Namen der Zone."
