L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "Importiert das vollständige Überschreibungs Setup des Absenders: Spezialisierungs- und bedingte Überschreibungswerte, Gruppen, deren benutzerdefinierte Freigabemodus Layouts und Stärkungszauber Manager Überschreibungen. Dies ersetzt ALLE Deine eigenen Überschreibungen. Aus = Deine bleiben unverändert."
