L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Enthält Schriftarten, benutzerdefinierte Farben, dunklen Modus, Akzentfarbe und UI Skalierung in diesem Export. Aus = nur die eigenen Einstellungen der ausgewählten Module exportieren, wodurch das globale Aussehen des Empfängers erhalten bleibt."
