L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "Enthält die Anker- & Größenanpassungs Beziehungen zwischen Modulen. Aus = nur die eigenen Positionen jedes Moduls ohne modulseitige Verknüpfung exportieren."
L["Include This Spell"] = "Diesen Zauber einschließen"
L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Enthält Deine Einstellungen für die erweiterte Blizzard-UI aus den Reitern Fenster Skins, Tooltips, Menüs & Popups. Diese sind accountweit: Wenn der Importeur zustimmt, überschreiben sie die Einstellungen dieses Spielers über ALLE seine Profile hinweg."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Enthält Dein vollständiges Überschreibungs Setup: Spezialisierungs- und bedingte Überschreibungswerte, Gruppen, deren benutzerdefinierte Freigabemodus Layouts und Stärkungszauber Manager Überschreibungen. Beim Import ersetzt dies die Überschreibungen des Empfängers vollständig."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Enthält das Zauber Layout Deines Abklingzeiten-Managers (welche Zauber auf welchen Leisten liegen) plus alle Einstellungen pro Zauber für alle von Dir gewählten Spezialisierungen."
