L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Behält Aktionsleiste 1 auf ihrer aktuellen Seite, wenn Du die Gestalt wechselst, in Verstohlenheit gehst oder die Haltung änderst, anstatt auf die Leiste dieser Form zu wechseln.\n\nTastenbelegungen folgen der Anzeige der Leiste, sodass die Taste immer das angezeigte Symbol wirkt. Das Wiederholen von Zaubern durch Gedrückthalten ist auf Aktionsleiste 1 deaktiviert, solange dies aktiv ist."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Behält Aktionsleiste 1 auf ihrer aktuellen Seite während des Himmelsreitens, anstatt auf die Himmelsreiten Leiste zu wechseln.\n\nDeine Himmelsreiten-Fähigkeiten liegen auf dieser Leiste, platziere sie also auf einer anderen Leiste, bevor Du dies aktivierst. Das Wiederholen von Zaubern durch Gedrückthalten ist auf Aktionsleiste 1 deaktiviert, solange dies aktiv ist."
L["Keep Buffs in Same Place"] = "Stärkungszauber an derselben Stelle halten"
L["Keep Colored (On CD)"] = "Farbfeil behalten (Auf Abklingzeit)"
L["Keep Enabled"] = "Aktiviert lassen"
L["Keep Focus Full Opacity"] = "Fokus bei voller Deckkraft halten"
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Hält den Tastenbelegungstext identisch, wenn Deine Aktionsleiste wechselt – Schurken-Verstohlenheit, Druidengestalten, Himmelsreiten. Deckt auch bedingte Makros wie \"/cast [bonusbar:1] Meucheln; Schattentanz\" ab, bei denen die Taste sonst zu dem jeweils aktiven Zweig springen würde.\n\nDie Taste ändert sich dann nur, wenn Du die Fähigkeit tatsächlich verschiebst oder neu belegst.\n\nStandardmäßig aktiviert. Gilt für alle CDM Leisten gleichzeitig."
L["Keep Keys on Bar Swap (global)"] = "Tasten bei Leistenwechsel behalten (global)"
L["Keep Mine"] = "Meins behalten"
L["Keep Raid Frames"] = "Schlachtzugsfenster behalten"
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Hält die Zauberleiste sichtbar (leer), wenn Du nicht zauberst, anstatt sie auszublenden."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Hält die GCD Leiste sichtbar (leer), wenn keine globale Abklingzeit läuft, anstatt sie auszublenden."
L["Keep the timer visible out of combat, showing the last fight's duration."] = "Hält den Timer außer Kampf sichtbar und zeigt die Dauer des letzten Kampfes an."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Hält dieses Menü geöffnet, wenn Du seine Tastenbelegung loslässt.\nZeige auf einen Eintrag und drücke die Taste 'Aktion auswählen', um ihn zu nutzen.\nDrücke die eigene Tastenbelegung des Menüs erneut oder Escape, um es zu schließen."
L["Keep"] = "Behalten"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Hält Auszahlungen des Handwerkerkonsortiums geschlossen, solange der Splitter von Dundun sein Maximum erreicht hat, und setzt das automatische Öffnen fort, nachdem Du Splitter ausgegeben hast."
L["Keeps Blizzard's own buff and debuff display and turns off the built-in Buffs and Debuffs bars. Custom bars keep working."] = "Behält Blizzards eigene Stärkungs- und Schwächungszauberanzeige bei und schaltet die integrierten Stärkungs- und Schwächungszauberleisten aus. Eigene Leisten funktionieren weiterhin."
