L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Zeigt die GCD Leiste nur für Spontanzauber an. Während des Zauberns oder Kanalisierens bleibt die Leiste ausgeblendet (die Zauberleiste zeigt bereits diesen Fortschritt)."
