L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Zeigt diese Leiste nur an, solange der verfolgte Stärkungszauber/die Abklingzeit aktiv ist. Deaktivieren, um jederzeit eine leere Leiste auf dem Bildschirm zu behalten."
L["Only Show When Hidden"] = "Nur anzeigen, wenn ausgeblendet"
L["Only Show when Mounted"] = "Nur auf Reittier anzeigen"
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Zeigt den Mauszeiger Kreis nur an, wenn die Maus ausgeblendet ist – also während Du die linke und/oder rechte Maustaste gedrückt hältst, um die Kamera zu schwenken oder Deinen Charakter zu bewegen."
L["Only Target Out of Combat"] = "Nur außer Kampf als Ziel wählen"
L["Only while airborne on a skyriding mount."] = "Nur während des Fliegens auf einem Himmelsreiten Reittier."
