L["Opacity of the cooldown swipe (the dark radial sweep); use the swatch to set its colour."] = "Deckkraft der Abklingzeit-Wischtextur (der dunkle radiale Verlauf); nutze das Farbfeld zur Farbeinstellung."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Deckkraft der Ressourcenfüllung; unter 100 scheint die Spielwelt durch die Füllung anstelle des Hintergrunds."
