L["Outline style override for all Chat text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil Überschreibung für allen Chattext. EUI Globale Kontur folgt der globalen Konturmodus Einstellung oben."
L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil Überschreibung für allen Abklingzeitmanagertext. EUI Globale Kontur folgt der globalen Konturmodus Einstellung oben."
L["Outline style override for all Damage Meters text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil Überschreibung für allen Schadensmetertext. EUI Globale Kontur folgt der globalen Konturmodus Einstellung oben."
