L["Remembers the Tank/Healer/DPS roles you last applied with and restores them the next time you sign up to a premade group (limited to roles your current spec can fill). Works with or without the reskin."] = "Merkt sich die Tank-/Heiler-/DPS-Rollen, mit denen Du dich zuletzt beworben hast, und stellt sie bei der nächsten Anmeldung für eine organisierte Gruppe wieder her (beschränkt auf Rollen, die Deine aktuelle Spezialisierung ausfüllen kann). Funktionierte mit oder ohne Skin."
