L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Erinnerungsschwellenwert, während Du dich in einem Dungeon vor dem Start eines Mythisch+-Schlüsselsteins befindest (Mythisch 0 / Schlüsselstein-Lobby). Stelle ihn hoch genug ein, um Stärkungszauber und Essen vor dem Pullen aufzufrischen, damit Du den Schlüsselstein mit ausreichender Dauer beginnst.\n0 = nur wenn vollständig abgelaufen.\nWird ignoriert, sobald der Schlüsselstein aktiv ist oder Du im Kampf bist (dann nur, wenn der Stärkungszauber vollständig abgelaufen ist)."
