L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Gestaltet Blizzards Fortschrittsleisten auf dem Bildschirm (Ereignisziele, Zähler auf Namensplaketten) im EUI-Look um. Erfordert ein Neuladen zum Übernehmen.\n\nDiese Leisten werden überzeichnet statt modifiziert. Falls das Spiel ihren Inhalt jemals als geschützt meldet, wird stattdessen die originale Leiste angezeigt.\n\nNutze das Zahnrad, um eine Mindestgröße festzulegen, damit Leisten auf verkleinerten Namensplaketten lesbar bleiben."
