L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "Skaliert die Verfolgungssymbole auf der Karte (Kräuter, Erz, Quest-Punkte). Die Karte selbst behält ihre Größe; andere Minikartenelemente bleiben unberührt."
