L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Legt die Akzentfarbe fest, die in allen EllesmereUI-Elementen (Reiter, Leuchten, Hervorhebungen, Rahmen) verwendet wird. Standardmäßig Deine Theme Farbe."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Legt die Schriftart für Namen fest, die über Spielern, NSCs und Gegnern in der Welt schweben.\n\nUnabhängig von der globalen Schriftart – Änderungen hier betreffen nicht das restliche UI und die globale Schriftart betrifft diese nicht.\n\n'Blizzard-Standard' lässt den Namenstext völlig unverändert.\n\n|cffff4d4dErfordert ein erneutes Einloggen oder einen Neustart von WoW, um wirksam zu werden.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Legt die Skalierung des gesamten Spiel-UI fest. Niedrigere Werte machen alles kleiner, höhere Werte alles größer."
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "Setzt die UI Skalierung auf den exakten, pixelperfekten Wert, der von anderen Addons verwendet wird. EllesmereUI erfordert keine Pixelperfektion."
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "Einstellungs Überschreibungen sind das leistungsstärkste und tiefgreifendste System in EllesmereUI. Ein paar Minuten mit diesem Video sparen Dir Stunden des eigenen Ausprobierens."
