L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "Zeigt jeden Stärkungszauber mit einer Dauer an (blendet dauerhafte aus). Nutze die Ausblenden-Zeile unten, um bestimmte Filter zu entfernen."
