L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Zeigt jeden Stärkungszauber an. Während dies aktiv ist, werden ausgewählte Filter unten vom Fenster ausgeblendet statt hinzugefügt."
L["Show every debuff in this indicator. Use the Hide lane below to remove specific filters."] = "Zeigt jeden Schwächungszauber in diesem Indikator an. Nutze die Ausblenden-Zeile unten, um bestimmte Filter zu entfernen."
