L["Show on FPS/MS Hover"] = "Beim Drüberbewegen über FPS/MS anzeigen"
L["Show on Target"] = "Beim Ziel anzeigen"
L["Show On"] = "Anzeigen bei"
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "Zeigt eine Nachkommastelle beim Gesundheitstext an: Gesundheitswerte wie 240.5k und Gesundheitsprozent wie 77.3%. Ressourcentext bleibt unbeeinflusst. Standardmäßig aus."
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Zeigt eine einfache Zauberleiste pro zaubernder feindlicher Namensplakette an, zusammengefasst in einer einzigen verschiebbaren Gruppe mit Zaubername, Ziel und Zaubertimer."
L["Show one sub-category per equipment set (named after the set) nested under Item Set Gear. Gear in several sets goes to the first one."] = "Zeigt eine Unterkategorie pro Ausrüstungsset (benannt nach dem Set) verschachtelt unter Ausrüstungsset-Ausrüstung. Ausrüstung in mehreren Sets wird dem ersten zugeordnet."
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Zeigt einmalige Videoguide-Plaketten neben neuen oder komplexen Funktionen. Jede Plakette verschwindet nach dem Anklicken für immer."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "Nur in Dungeons, Schlachtzügen, Arenen oder Schlachtfeldern anzeigen. Mit 'Kampf' kombinieren, um nur im Instanzkampf anzuzeigen."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "Nur im Kampf anzeigen. Mit 'Instanzen' kombinieren, um nur im Instanzkampf anzuzeigen."
L["Show Out of Combat"] = "Außerhalb des Kampfes anzeigen"
L["Show Over Dispels"] = "Über Banneffekten anzeigen"
L["Show Overshield"] = "Überhangschild anzeigen"
L["Show Own on All Specs"] = "Eigene auf allen Spezialisierungen anzeigen"
L["Show page up/down arrows next to Action Bar 1 for cycling through action bar pages 1-6."] = "Zeigt Seite rauf/runter Pfeile neben Aktionsleiste 1 zum Durchblättern der Aktionsleistenseiten 1–6."
L["Show Paging Arrows"] = "Seitenpfeile anzeigen"
L["Show Periodic Damage"] = "Periodischen Schaden anzeigen"
L["Show Pet Melee Damage"] = "Begleiter Nahkampfschaden anzeigen"
L["Show Pet Spell Damage"] = "Begleiter Zauberschaden anzeigen"
L["Show Pinned & Recent Tips"] = "Tipps für angepinnte & neueste Gegenstände anzeigen"
L["Show Pinned Items"] = "Angepinnte Gegenstände anzeigen"
L["Show Placed-Marker Pips"] = "Indikatoren für platzierte Markierungen anzeigen"
L["Show player nicknames from supported addons instead of character names on your main frames."] = "Zeigt Spieler Spitznamen unterstützter Addons anstelle von Charakternamen auf Deinen Hauptfenstern."
L["Show Player Titles"] = "Spielertitel anzeigen"
L["Show Portrait"] = "Porträt anzeigen"
L["Show Power Bar For"] = "Ressourcenleiste anzeigen für"
L["Show Power Bar"] = "Ressourcenleiste anzeigen"
L["Show Preview"] = "Vorschau anzeigen"
L["Show PvP Item Level"] = "PvP-Gegenstandsstufe anzeigen"
L["Show PvP"] = "PvP anzeigen"
L["Show Quest Icons"] = "Questsymbole anzeigen"
L["Show Queue Timer"] = "Warteschlangentimer anzeigen"
L["Show Raid Frames Tooltip"] = "Tooltip für Schlachtzugsfenster anzeigen"
L["Show Raid Marker"] = "Schlachtzugmarkierung anzeigen"
L["Show Raid Tools"] = "Schlachtzugswerkzeuge anzeigen"
L["Show Raw Rating"] = "Rohwertung anzeigen"
L["Show Raw Values"] = "Rohwerte anzeigen"
L["Show Ready Check"] = "Bereitschaftsabfrage anzeigen"
L["Show Recent Items"] = "Neueste Gegenstände anzeigen"
L["Show Region Icons"] = "Regionssymbole anzeigen"
L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Erinnerungen anzeigen, wenn die verbleibende Stärkungszauberzeit unter dieser Minutenzahl liegt.\n0 = nur wenn vollständig abgelaufen.\nIn Kämpfen und M+-Schlüsselsteinen ignoriert (dann nur, wenn abgelaufen)."
L["Show Role Check"] = "Rollenabfrage anzeigen"
L["Show Role"] = "Rolle anzeigen"
L["Show rune count in center and remove recharge text/animation"] = "Runenanzahl zentriert anzeigen und Aufladungstext/-animation entfernen"
L["Show S for Seconds"] = "'S' für Sekunden anzeigen"
L["Show Secondary"] = "Sekundär anzeigen"
L["Show Set Name on Gear"] = "Setnamen auf Ausrüstung anzeigen"
L["Show shield effects on preview"] = "Schildeffekte in Vorschau anzeigen"
L["Show Shield Icon"] = "Schildsymbol anzeigen"
L["Show Sidebar on Right"] = "Seitenleiste rechts anzeigen"
L["Show Silver and Copper"] = "Silber und Kupfer anzeigen"
L["Show Sort Icon"] = "Sortiersymbol anzeigen"
L["Show Spark"] = "Funken anzeigen"
L["Show Speed Text"] = "Geschwindigkeitstext anzeigen"
L["Show Spell Icon"] = "Zaubersymbol anzeigen"
L["Show Spell ID on Tooltip"] = "Zauber-ID im Tooltip anzeigen"
L["Show Spell Name"] = "Zaubernamen anzeigen"
L["Show Spell Target"] = "Zauberziel anzeigen"
L["Show Spell Tooltips on Hover"] = "Zaubertooltips beim Drüberbewegen anzeigen"
L["Show Stacks"] = "Stapel anzeigen"
L["Show Still Available Column"] = "Spalte 'Noch verfügbar' anzeigen"
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Erfolgreiche Zauberunterbrechungen im Kontrollverlust-Symbolplatz anzeigen.\n\nAufgrund von Addon-Einschränkungen beträgt die angezeigte Dauer pauschal 4 Sekunden für alle Klassen, ist also nicht zu 100 % exakt."
L["Show Tanks in Extra Group"] = "Tanks in Extra Gruppe anzeigen"
L["Show Tanks Options"] = "Optionen für Tanks Anzeige"
L["Show Tertiary Stats"] = "Tertiäre Attribute anzeigen"
L["Show Tertiary"] = "Tertiär anzeigen"
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Zeigt die Leiste mit ihrer Füllfarbe gefüllt, solange keine globale Abklingzeit läuft, anstelle der Hintergrundfarbe."
L["Show the border style and size controls for the timer bars."] = "Zeigt die Rahmenstil- und Größeneinstellungen für die Timerleisten an."
L["Show the bright spark at the leading edge of the cast bar fill."] = "Zeigt den hellen Funken an der Vorderkante der Zauberleistenfüllung."
L["Show the charge and stack counters on this bar's icons."] = "Zeigt die Aufladungs- und Stapelzähler auf den Symbolen dieser Leiste."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected."] = "Zeigt den Herstellungsqualitätsrang bei verfolgten Gegenständen an, passend zum Rangsymbol auf den Aktionsleisten."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "Zeigt die Erweiterungs-Übersichtsseite (Omnium-Folio) auf der Minikarte. Nutze das Zahnrad zur Positionierung."
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Zeigt die Fokus Kickleiste auf der Namensplakette Deines aktuellen Ziels anstelle Deines Fokusziels an."
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "Zeigt den Standard Zaubertooltip des Spiels, wenn Du im Aufschlüsselungsfenster über einen Zauber fährst."
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "Zeigt das Anführer-/Assistentensymbol im Kampf. Deaktivieren zum Ausblenden während des Kampfes."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Zeigt den Hervorhebungsrahmen beim Drüberbewegen der Hauptfenster auf diesem Fenster an. Deaktivieren, damit dieses Fenster die Farbe bei Mouseover nie ändert."
L["Show the Mythic+ teleport section in the tooltip. Ready rows are click-to-teleport."] = "Zeigt den Mythisch+ Teleportabschnitt im Tooltip. Bereite Zeilen sind klickbar zum Teleportieren."
L["Show the name of who the boss is casting on."] = "Zeigt den Namen des Ziels an, auf das der Boss zaubert."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Zeigt das Begleiterfenster immer an, wenn Du einen Begleiter hast, ungeachtet der Sichtbarkeitseinstellungen des Spielerfensters."
L["Show the Pinned Items category in the sidebar and content grid."] = "Zeigt die Kategorie 'Angepinnte Gegenstände' in der Seitenleiste und im Inhaltsraster an."
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "Zeigt auf freundlichen Namensplaketten den Spielertitel neben dem Namen und/oder die Gilde in einer Zeile darunter an."
L["Show the Recent Items category in the sidebar and content grid for newly acquired items."] = "Zeigt die Kategorie 'Neueste Gegenstände' in der Seitenleiste und im Inhaltsraster für neu erworbene Gegenstände an."
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "Zeigt den Auflade Countdown bei Zaubern mit Aufladungen an, selbst wenn noch eine Aufladung verfügbar ist. Wenn aus, erscheint der Timer erst bei 0 Aufladungen (Blizzard-Standard)."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Zeigt den Ressourcentext nur, während die Ressourcenleiste ausgeblendet ist (deaktiviert, gefiltert, ohne Ressource oder durch 'Ressourcenleiste ausblenden, wenn Klassenressource' versteckt). Aus = Text immer anzeigen."
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "Zeigt den rotierenden Abklingzeitenrand bei jeder Abklingzeit auf dieser Leiste. 'Aufladerand ausblenden' überschreibt dies weiterhin für einzelne Aufladezauber."
L["Show the seasonal Earned / Cap column in the crest table."] = "Zeigt die saisonale Spalte 'Erhalten / Obergrenze' in der Wappentabelle an."
L["Show the selected action's name next to the selected icon."] = "Zeigt den Namen der ausgewählten Aktion neben dem ausgewählten Symbol an."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "Zeigt den Tracker als Wiederbelebensymbol oder als kompakte Textzeile mit Aufladungen und Zeit bis zur nächsten an."
L["Show the unit's tooltip when hovering the frame itself."] = "Zeigt den Tooltip der Einheit beim Drüberbewegen über das Fenster selbst an."
L["Show this indicator's buffs in the exact order you arrange (the first 10 arranged buffs are guaranteed; any beyond follow the default sorting)."] = "Zeigt die Stärkungszauber dieses Indikators in der exakt von Dir festgelegten Reihenfolge (die ersten 10 eingestellten Stärkungszauber sind garantiert; alle weiteren folgen der Standardsortierung)."
L["Show this indicator's buffs on every spec of your class, not only this spec."] = "Zeigt die Stärkungszauber dieses Indikators für jede Spezialisierung Deiner Klasse an, nicht nur für diese."
L["Show Timer Bar"] = "Timerleiste anzeigen"
L["Show Timer Text"] = "Timertext anzeigen"
L["Show Timer"] = "Timer anzeigen"
L["Show Title"] = "Titel anzeigen"
L["Show Tooltip Data"] = "Tooltipdaten anzeigen"
L["Show Tooltip For"] = "Tooltip anzeigen für"
L["Show Tooltip on Hover"] = "Tooltip beim Drüberbewegen anzeigen"
L["Show Tooltip"] = "Tooltip anzeigen"
L["Show Tooltips"] = "Tooltips anzeigen"
L["Show top 15 entries instead of 8."] = "Zeigt die besten 15 Einträge anstelle von 8 an."
L["Show Top Line"] = "Obere Zeile anzeigen"
L["Show Total Duration"] = "Gesamtdauer anzeigen"
L["Show total equipped durability above the character model, colored from green to red."] = "Zeigt die gesamte Haltbarkeit der angelegten Ausrüstung über dem Charaktermodell an, eingefärbt von Grün bis Rot."
L["Show Unit Target"] = "Einheitenziel anzeigen"
L["Show Upgrade Track"] = "Aufwertungspfad anzeigen"
L["Show Veteran"] = "Veteran anzeigen"
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "Zeigt Waffenöl- und Waffenverzauberungssymbole am Anfang dieser Leiste an. Da es sich um Waffenverzauberungen und nicht um Auren handelt, werden sie unabhängig von den obigen Optionen angezeigt – und das Aurenraster wird nach innen verschoben, um Platz zu machen."
L["Show When Missing"] = "Anzeigen, wenn fehlend"
L["Show When Solo"] = "Anzeigen, wenn alleine"
L["Show When Spellbook Is Open"] = "Anzeigen, wenn Zauberbuch geöffnet ist"
L["Show When"] = "Anzeigen wenn"
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Zeigt an, auf wen jeder Zauber gewirkt wird, exakt wie auf den Zauberleisten der Namensplaketten."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Zeigt an, auf wen der Zauber gewirkt wird, exakt wie auf den Zauberleisten der Namensplaketten."
L["Show Without Item in Bags"] = "Ohne Gegenstand in den Taschen anzeigen"
L["Show World MS"] = "Welt-MS anzeigen"
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "Zeigt Deine eigenen Klassen-Stärkungszauber auf allen Spezialisierungen an, nicht nur auf der verfolgten Heiler Spezialisierung."
L["Show/Hide Hitbox Overlay"] = "Trefferzonen Überlagerung ein-/ausblenden"
L["Show/Hide on Preview"] = "In Vorschau ein-/ausblenden"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Wert der Überschreibung '%s' wird angezeigt. Im Bearbeitungsmodus dieser Überschreibung anpassen."
L["Showing this aura from any caster; click for your casts only."] = "Diese Aura wird von allen Zaubernden angezeigt; klicken, um nur eigene Zauber anzuzeigen."
L["Showing this aura from your casts only; click for any caster."] = "Diese Aura wird nur von Deinen Zaubern angezeigt; klicken, um von allen Zaubernden anzuzeigen."
L["Shown At Cursor"] = "Am Mauszeiger angezeigt"
L["Shown"] = "Angezeigt"
L["Shows a bar that fills over the global cooldown."] = "Zeigt eine Leiste an, die sich während der globalen Abklingzeit füllt."
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Zeigt eine klickbare Liste von Online Freunden und Gildenmitgliedern in den Tooltips der Geselligkeit- und Gildentasten an."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Zeigt eine farbige Überlagerung am Ende der Zauberleiste, die Deine Netzwerklatenz für jeden Zauber darstellt. Hilft beim richtigen Timing der Zauberwarteschlange."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin."] = "Zeigt eine Countdownleiste unter dem Einladungs Popup an, die angibt, wie viel Zeit zum Annehmen verbleibt."
L["Shows a faint white wash over each block on mouseover."] = "Zeigt bei Mouseover eine schwache weiße Hervorhebung über jedem Block."
L["Shows a house or globe icon marking which latency each value is."] = "Zeigt ein Haus- oder Globussymbol, das anzeigt, um welche Latenz es sich handelt."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Zeigt eine große Warnung auf dem Bildschirm an (z. B. 'Spieler GESTORBEN!'), wann immer ein Gruppen- oder Schlachtzugsmitglied stirbt. Nutzen den Freigabemodus zum Repositionieren."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Zeigt beim Betreten und/oder Verlassen des Kampfes einen großen Text auf dem Bildschirm an (z. B. '+Kampf' / '-Kampf'). Nutzen den Freigabemodus zum Repositionieren."
L["Shows a mana percentage row for every healer in your group as its own movable text display. Position it in Unlock Mode."] = "Zeigt eine Mana Prozentzeile für jeden Heiler in Deiner Gruppe als eigene verschiebbare Textanzeige an. Im Freigabemodus positionieren."
L["Shows a map icon of the friend's region if they are not playing within your region"] = "Zeigt ein Kartensymbol der Region des Freundes an, wenn er nicht in Deiner Region spielt"
L["Shows a movable strip of recent spell icons. Shift-drag to reposition."] = "Zeigt eine verschiebbare Leiste der letzten Zaubersymbole an. Umschalt-Ziehen zum Positionieren."
L["Shows a popup with party and guild keystones when typing /keys."] = "Zeigt beim Tippen von /keys ein Popup mit Gruppen- und Gilden-Schlüsselsteinen an."
L["Shows a rest icon while your character is resting."] = "Zeigt ein Erholtsymbol an, während sich Dein Charakter erholt."
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Zeigt einen einzelnen Schwächungszauber 'Blutpest' auf feindlichen Namensplaketten anstelle von einer pro Kopie."
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Zeigt einen kleinen weißen Teilstrich auf der Zauberleiste an dem Punkt, an dem der Zauber sein wird, sobald Deine Unterbrechung bereit ist."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Zeigt einen kleinen weißen Teilstrich an der Stelle, an der der Zauber sein wird, sobald Deine Unterbrechung bereit ist."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Zeigt eine spezielle Farbe für Namensplaketten, auf denen ein anderer Tank in Deinem Schlachtzug Aggro hat."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Zeigt eine spezielle Farbe für Gegner (außer Zauberer/Minibosse), auf denen Du keine Aggro hast."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Zeigt eine spezielle Farbe für Gegner (außer Zauberer/Minibosse), auf denen Du Aggro hast."
L["Shows a standalone window with spell cast history as bars. Matches your Damage Meters styling."] = "Zeigt ein freistehendes Fenster mit dem Zauberverlauf als Leisten. Entspricht dem Stil Deiner Schadensmeter."
L["Shows an envelope icon when you have unread mail."] = "Zeigt ein Umschlagsymbol bei ungelesener Post."
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Zeigt jeden Schwächungszauber mit Banneffekt (Magie, Fluch, Krankheit, Gift, Blutungs Effekt), selbst wenn Du ihn nicht entfernen kannst"
L["Shows Blizzard's default icon slot background texture behind empty action bar slots."] = "Zeigt Blizzards Standard Symbolhintergrundtextur hinter leeren Aktionsleisten Plätzen."
L["Shows each healer's name before the number while in a raid. In a party the display always shows numbers only."] = "Zeigt im Schlachtzug den Namen jedes Heilers vor der Zahl an. In einer Gruppe werden immer nur Zahlen angezeigt."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Zeigt die verstrichene / Gesamtdauer an (z. B. 0.4 / 2.0), anstatt von der Gesamtdauer herunterzuzählen."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Zeigt Gegenstandsstufe und sekundäre Attribute im Tooltip der Charaktertaste an."
L["Shows only auras with a dispel type you can dispel"] = "Zeigt nur Auren mit einem Banneffekt an, den Du bannen kannst"
L["Shows only buffs that can be canceled"] = "Zeigt nur Stärkungszauber an, die abgebrochen werden können"
L["Shows only buffs you can spellsteal or purge"] = "Zeigt nur Stärkungszauber an, die Du rauben oder reinigen kannst"
L["Shows only crowd-control auras"] = "Zeigt nur Kontrollverlust Auren an"
L["Shows only debuffs applied by bosses"] = "Zeigt nur von Bossen angewendete Schwächungszauber an"
L["Shows only debuffs Blizzard flags as important"] = "Zeigt nur Schwächungszauber an, die von Blizzard als wichtig markiert sind"
L["Shows only debuffs flagged for your role"] = "Zeigt nur Schwächungszauber an, die für Deine Rolle markiert sind"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Zeigt nur Schwächungszauber aus Blizzards ausgewähltem Schlachtzugs-Set an"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Zeigt nur Schwächungszauber an, die nicht von Spielern oder Begleitern verursacht wurden."
L["Shows only external defensive cooldowns cast on the unit"] = "Zeigt nur externe defensive Abklingzeiten an, die auf die Einheit gewirkt wurden"
L["Shows only major defensive cooldowns"] = "Zeigt nur große defensive Abklingzeiten an"
L["Shows only the buffs you apply"] = "Zeigt nur von Dir angewendete Stärkungszauber an"
L["Shows only the Debuffs you apply"] = "Zeigt nur von Dir angewendete Schwächungszauber an"
L["Shows only the stricter in-combat subset of the raid set"] = "Zeigt nur die strengere Teilmenge des Schlachtzug Sets für den Kampf"
L["Shows silver and copper, not just gold."] = "Zeigt Silber und Kupfer an, nicht nur Gold."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Startet als kleines Symbol, und die Tastenbelegung schaltet zwischen dem Symbol und den vollständigen Fenstern um."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Zeigt den Text 'Funktion deaktivieren' unter der Teleport Taste an."
L["Shows the active talent loadout name."] = "Zeigt den Namen der aktiven Talentkonfiguration an."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Zeigt die ungefähre Entfernung zu Deinem aktuellen Ziel als verschiebbaren Bildschirmtext an (Standard 30–35)."
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Zeigt die ungefähre Entfernung zu Deinem aktuellen Ziel auf dessen Namensplakette als Reichweitenbereich an (z. B. 15+)."
L["Shows the audio icon next to the volume bar."] = "Zeigt das Audio-Symbol neben der Lautstärkeleiste an."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Zeigt die Mobilitätszauber der ausgewählten Klassen als ablaufende Abklingzeit an."
L["Shows the coin icon next to the amount."] = "Zeigt das Münzsymbol neben dem Betrag an."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "Zeigt das Rautensymbol für den Verbrauchsgüter-Rang (Qualität) auf AktionsTasten an."
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "Zeigt die Taste 'In Schlachtzug umwandeln', die in einem Schlachtzug 'In Gruppe umwandeln' lautet."
L["Shows the currency icon next to the amount."] = "Zeigt das Währungssymbol neben dem Betrag an."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Zeigt den Beschreibungstext der Währung im Tooltip. Deaktivieren für einen kompakten Tooltip mit nur Name und Betrag."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Zeigt die Taste 'Gruppe auflösen'. Ausblenden schützt dauerhaft vor versehentlichen Klicks."
L["Shows the icon next to the durability readout."] = "Zeigt das Symbol neben der Haltbarkeitsanzeige an."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Zeigt die Gegenstandsstufe auf jedem Gegenstand im Ausrüstungs Popup des Charakterfensters an, eingefärbt nach Qualität."
L["Shows the item level on weapons and armor a vendor sells."] = "Zeigt die Gegenstandsstufe bei Waffen und Rüstungen an, die ein Händler verkauft."
L["Shows the items as a list instead of pages."] = "Zeigt Gegenstände als Liste statt in Seiten an."
L["Shows the map pin next to the zone name."] = "Zeigt die Kartenstecknadel neben dem Zonennamen an."
L["Shows the marker icon next to the coordinates."] = "Zeigt das Markierungssymbol neben den Koordinaten an."
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Zeigt das Drachenemblem im Namensplaketten Stil bei Elite-, Selten-Elite- und seltenen Zielen an."
L["Shows the online friend and guild counters."] = "Zeigt die Zähler für Online Freunde und Gildenmitglieder an."
L["Shows the overlay only for debuffs you can currently dispel."] = "Zeigt die Überlagerung nur für Schwächungszauber an, die Du aktuell bannen kannst."
L["Shows the profession icons next to the text."] = "Zeigt die Berufssymbole neben dem Text an."
L["Shows the raid target marker icon on boss frames."] = "Zeigt das Zielmarkierungssymbol auf Bossfenstern an."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Zeigt die Taste 'Rollenabfrage'. Deaktivieren, damit die verbleibenden Tasten die Lücke schließen."
L["Shows the rotation-helper ring on the button holding the One Button Assist action."] = "Zeigt den Rotationshelfer Ring auf der Taste an, die die Ein-Tasten Assistenz enthält."
L["Shows the spec icon next to the text."] = "Zeigt das Spezialisierungssymbol neben dem Text an."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Zeigt die Zielmarkierung direkt vor dem Namenstext des Gegners an."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Zeigt Zone und Subzone zusammen anstelle der Subzone alleine an."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Zeigt Teilstriche bei kanalisierten Zaubern. Nur unterstützte Zauber werden angezeigt."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Zeigt an, wann Deine Unterbrechung während eines Zaubers bereit sein wird."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Zeigt an, wann Deine Unterbrechung während eines gegnerischen Zaubers bereit sein wird."
L["Shows your free bag slots."] = "Zeigt Deine freien Taschenplätze an."
