L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "Kleinste Bildschirmgröße, in der eine angepasste Leiste gezeichnet wird.\n\nWidget Leisten auf einer Namensplakette erben deren Skalierung, sodass sie bei kleinen Einheiten winzig erscheinen. Unterhalb dieser Größe wird die Leiste stattdessen vergrößert, einschließlich Text.\n\nAuf 0 setzen, um Blizzards Größe exakt wiederzugeben."
