L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Die 'Du wurdest in eine Gruppe eingeladen' Dialoge mit Deiner Rolle und Annehmen / Ablehnen."
L["The \"You received\" popups for loot, currency, and upgrades."] = "Die 'Du hast erhalten' Popups für Beute, Währung und Aufwertungen."
L["The achievement window: categories, rows, progress bars, and search."] = "Das Erfolgsfenster: Kategorien, Zeilen, Fortschrittsleisten und Suche."
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "Das benutzerdefinierte %s der aktiven Überschreibung ist an diese Seite gebunden. Verlasse den Reiter %s, um zu einer anderen Überschreibung zu wechseln."
L["The addon manager: list rows, checkboxes, and buttons."] = "Der Addon Manager: Listenzeilen, Kontrollkästchen und Tasten."
L["The amount of damage you can take"] = "Die Schadensmenge, die Du erleiden kannst"
L["The Armory"] = "Das Arsenal"
L["The auction house: browse, sell, and my auctions views."] = "Das Auktionshaus: Stöbern-, Verkaufen- und 'Meine Auktionen' Ansichten."
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "Die Hintergrundfarbe hinter Leisten im dunklen Modus (Einheitenfenster, Schlachtzugsfenster, Ressourcenleisten)."
L["The Blinding Vale"] = "Das Blendende Tal"
L["The class and profession trainer window: skill list, train button, and cost display."] = "Das Klassen- und Berufsausbilderfenster: Fertigkeitenliste, Ausbilden Taste und Kostenanzeige."
L["The Combat Indicator is not available for the Focus frame."] = "Der Kampfindikator ist für das Fokusfenster nicht verfügbar."
L["The customer crafting orders window: browse, order form, and my orders."] = "Das Kunden Handwerksauftragsfenster: Stöbern, Auftragsformular und 'Meine Aufträge'."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "Die Schaden- und Tank-Variante von Light of Nitex. Derselbe Stil mit klarem Fokus auf Deine Rotation, Procs und Abklingzeiten direkt im Mittelpunkt."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "Die Schadensverursacher Variante von Midnight Lily. Ein fokussiertes, aufgeräumtes Layout, das Deine Rotation und Abklingzeiten im Mittelpunkt hält."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "Das dunkle Gegenstück zu Lazar's Dawn. Ein stimmungsvolles, kontrastreiches Layout, das den Fokus voll auf dem Kampf hält."
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "Das Tiefen Schwierigkeitsfenster: Stufen Auswahl, Belohnungsliste und Betreten Taste. Die Karteneigenschaften Zeile bleibt unverändert."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "Die Anzeigesprache für das EllesmereUI Optionsfenster. 'Auto' folgt Deinem Spielclient. Nicht übersetzter Text fällt auf Englisch zurück."
L["the EllesmereUI theme"] = "das EllesmereUI Theme"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "Die einfarbige Füllfarbe, die Leisten im dunklen Modus verwenden (Einheitenfenster, Schlachtzugsfenster, Ressourcenleisten)."
L["the Frame Source to be EllesmereUI"] = "dass die Fensterquelle EllesmereUI ist"
L["The gap between a nested menu's icons and the entry that opens it."] = "Der Abstand zwischen den Symbolen eines verschachtelten Menüs und dem Eintrag, der es öffnet."
L["The gem socketing window with squared gem slots."] = "Das Sockelfenster mit quadratischen Edelsteinplätzen."
L["The Guild & Communities window: roster, chat, and the community list."] = "Das Gilden- & Communitys Fenster: Mitgliederliste, Chat und Community Liste."
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "Die Hervorhebungs Überlagerung auf einer Zaubertaste, während diese die aktive/aktuelle Aktion ist. Deaktivieren zum Ausblenden."
L["The housing dashboard window background, border, and title bar."] = "Hintergrund, Rahmen und Titelleiste des Behausung Übersichtsfensters."
L["The item conversion window (catalyst and similar kiosks)."] = "Das Gegenstandsumwandlungs Fenster (Katalysator und ähnliche Stände)."
L["The item preview / transmog dressing room window."] = "Das Gegenstandsvorschau- / Transmogrifikations Ankleideraumfenster."
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "Das Gegenstandsaufwertungs Fenster: Aufwertungsplatz, Pfadauswahl, Kosten und Währungsleiste."
L["The loot window: item rows with squared icons, kept item quality colors."] = "Das Beutefenster: Gegenstandszeilen mit quadratischen Symbolen und beibehaltenen Gegenstandsqualitätsfarben."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "Der Makro-Editor: Reiter, Symbolraster, Textfeld und Tasten."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "Das Postfach: Posteingangszeilen, Post senden, Post öffnen und Anhangplätze."
L["the Modern background style"] = "der moderne Hintergrundstil"
L["the module"] = "das Modul"
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "Das monatliche Kalenderraster, Ereignisdialoge und Navigationspfeile."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "Die maximale Anzahl gleichzeitig angezeigter Zauberleisten. Zusätzliche Zauberer erhalten eine Leiste, sobald eine frei wird."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "Die Bedarf / Gier / Passen-Würfelpopups mit quadratischem Symbol und flachem Würfeltimer."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "Das NSC Dialogfenster: Begrüßungstext, Gesprächs- und Questoptionen sowie Verabschieden Taste."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "Das NSC Questfenster: Questdetails, Fortschritts- und Belohnungsfenster sowie die Mehrfach Questbegrüßungsliste."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "Die Überlagerung auf dem Symbol, wenn Du mit der Maus über eine Zaubertaste fährst"
L["The overlay that appears on the icon when you press and hold a spell button"] = "Die Überlagerung auf dem Symbol, wenn Du eine Zaubertaste gedrückt hältst"
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "Das Fenster, das beim Drüberbewegen über das Dungeonsuche Auge der Minimap erscheint: Warteschlangentitel, Rollensymbole, Anzahl und Zeit."
L["The pasted string could not be read completely. Please paste it again."] = "Der eingefügte String konnte nicht vollständig gelesen werden. Bitte erneut einfügen."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "Das Fenster für ausstehende Würfe: Begegnungsauswahl, Würfeltimer und Ergebniszeilen."
L["The Pet Bar cannot use group-based visibility."] = "Die Begleiterleiste kann keine gruppenbasierte Sichtbarkeit nutzen."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "Das Spielerzauber Fenster: Talente, Spezialisierungsauswahl und Zauberbuch."
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "Das Handelsfenster zwischen Spielern: Rahmen, beide Gegenstandsspalten, Verzauberungsplätze, Geldzeilen und Tasten. Gegenstandssymbole sind quadratisch mit Seltenheitsrahmen."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "Das Handwerksfenster: Rezeptliste, Schemata, Spezialisierungen und Handwerksaufträge."
L["The professions overview book with squared icons and flat progress bars."] = "Das Berufsübersichts Buch mit quadratischen Symbolen und flachen Fortschrittsleisten."
L["the Randomly trigger"] = "der Auslöser 'Zufällig'"
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "Die Bereitschaftsabfrage mit Ja / Nein Tasten plus der Antwortliste des Initiators."
L["The ready check prompt with its Yes / No buttons."] = "Die Bereitschaftsabfrage mit ihren Ja / Nein Tasten."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "Das Rezeptvorschau Fenster, das bei einem verlinkten Rezept oder betrachteten Handwerker angezeigt wird."
L["The Ring of Valor"] = "Ring des Valor"
L["The Rookery"] = "Der Krähenhorst"
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "Das unverwechselbare EllesmereUI Layout exakt wie entworfen. Lebendige Klassenfarben, klare Abklingzeiten Verfolgung und alle Module in perfekter Harmonie."
L["The single stack threshold is off while Multiple Thresholds is on."] = "Der einzelne Stapelschwellenwert ist aus, während 'Mehrere Schwellenwerte' an ist."
L["The size of your mana pool"] = "Die Größe Deines Manavorrats"
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "Rahmen, Rand, Titelleiste, Battle.net-Leiste, Suchfelder, Filter-Dropdowns und Tasten des Geselligkeit Fensters."
L["The standard buff grid"] = "Das Standard Stärkungszauber Raster"
L["The standard debuff grid"] = "Das Standard Schwächungszauber Raster"
L["The stricter in-combat subset of the raid set."] = "Die strengere Teilmenge des Schlachtzug Sets für den Kampf."
L["The transmogrification window at the transmogrifier."] = "Das Transmogrifikationsfenster beim Transmogrifizierer."
L["The vendor window: item list, buyback, and bottom money bar."] = "Das Händlerfenster: Gegenstandsliste, Rückkauf und untere Geldleiste."
L["The Venomous Abyss"] = "Der Giftige Abgrund"
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "Der breiteste Winkel, über den sich die Einträge einer Verschachtelung verteilen können. Sie bleiben auf einem Ring, solange sie darauf passen; der Rest wechselt auf einen zweiten, äußeren Ring."
L["The widest angle a nest's entries may spread over."] = "Der breiteste Winkel, über den sich die Einträge einer Verschachtelung verteilen können."
L["The world map window chrome and the quest log side panel."] = "Der Rahmen des Weltkartenfensters und das Seitenfeld des Questlogs."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Thematisch angepasste Blizzard Fenster: Skins, Tooltips, Menüs, Popups, Drachenreiten HUD."
L["These are the same settings found on each module's own pages, not separate ones."] = "Dies sind dieselben Einstellungen, die sich auch auf den jeweiligen Modulseiten befinden, keine separaten."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Diese Spezialisierungen enthalten Überschreibungswerte, die von keinem Gruppen Bearbeitungsmodus mehr erreicht werden können (hinterlassen durch Mitgliedschaftsänderungen). Sie gelten weiterhin. Entferne eine, um diese Spezialisierung zum gemeinsamen Standard zurückzuführen."
L["Thick"] = "Dick"
L["Thickness in physical pixels. -1 follows the Debuff Manager's Border setting, 0 hides the dispel color border."] = "Dicke in physischen Pixeln. -1 folgt der Rahmeneinstellung des Schwächungszauber-Managers, 0 blendet den Bannfarben-Rahmen aus."
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Dicke jedes Pixelleuchtens, das den Tasten dieser Leiste zugewiesen ist. Zuweisung per Rechtsklick auf ein Symbol in der Vorschau."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Dicke des Pixelleuchtens, das auf die Stärkungszauber Symbole dieser Leiste angewendet wird."
L["Thickness"] = "Dicke"
L["Third Timer"] = "Dritter Timer"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Diese Aktionsleiste wird auch als Mondkingestalt-Leiste verwendet.\nDas Ändern von Zaubern auf dieser Leiste für einen Druiden ändert sie auch auf Deiner Mondkingestalt Leiste."
L["this action bar"] = "diese Aktionsleiste"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Diese Leiste hat einen zusätzlichen Leistenversatz (X %1$s, Y %2$s) in ihren Optionen eingestellt. Der Freigabemodus zeigt die Basisposition; der Versatz wird nach dem Beenden wieder angewendet."
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Diese Leiste skaliert ihre Blöcke selbst, daher kann die Breite für diesen Block nicht gewählt werden."
L["This bar will always be attached to your current target's nameplate"] = "Diese Leiste wird immer an der Namensplakette Deines aktuellen Ziels angebracht"
L["This bar will always be attached to your focus target's nameplate"] = "Diese Leiste wird immer an der Namensplakette Deines Fokusziels angebracht"
L["This bar will only show if you have an enemy targeted"] = "Diese Leiste wird nur angezeigt, wenn Du einen Gegner als Ziel hast"
L["this bar"] = "diese Leiste"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Dieser Block ist bereits der Block 'Verbleibenden Platz füllen'. Wähle einen anderen Block, um diese Rolle zu verschieben."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Dies kann nicht ändern, welche Zauber im Blizzard CDM verfolgt werden.\nEs wird empfohlen, auch Dein Blizzard CDM Layout für jede hier gewählte Spezialisierung zu teilen."
L["This cannot be undone. Export your own profile as a backup first."] = "Dies kann nicht rückgängig gemacht werden. Exporte zuerst Dein eigenes Profil als Backup."
L["This condition is coming in a future update."] = "Diese Bedingung folgt in einem zukünftigen Update."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Steuerungskontrolle hat die Richtung geändert: Sie kopiert nun VON dem gewählten Fenster. Bestätigen kopiert alle geteilten Einstellungen VON %1$s NACH %2$s."
L["This element cannot use group-based visibility."] = "Dieses Element kann keine gruppenbasierte Sichtbarkeit nutzen."
L["This element doesn't support both Height and Width matching"] = "Dieses Element unterstützt nicht gleichzeitig Höhen- und Breitenanpassung."
L["This element will only show while you are inside a house or plot"] = "Dieses Element wird nur angezeigt, während Du dich in einem Haus oder auf einem Grundstück befindest."
L["This element will only show while you are mounted"] = "Dieses Element wird nur angezeigt, während Du aufgesessen bist."
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Dieser Export enthält profilübergreifende Einstellungen (Komfortfunktionen, HoverCast etc.), die beim Importeur überschrieben werden. NICHT EMPFOHLEN für die öffentliche Weitergabe."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Diese Funktion optimiert Deine Grafikeinstellungen im Spiel für die beste Kombination aus hohen FPS und visueller Klarheit.\n\nDu kannst alle Änderungen jederzeit über 'Meine Einstellungen wiederherstellen' rückgängig machen.\n\nWas geändert wird:\n\nSchattenqualität - Gut (ausgewogen)\nFlüssigkeitendetails - Deaktiviert\nPartikeldichte - Ultra (wichtige Zaubereffekte bleiben)\nSSAO - Deaktiviert\nTiefeneffekte - Deaktiviert\nBerechnungseffekte - Deaktiviert\nKonturmodus - Deaktiviert\nTexturauflösung - Hoch\nZauberdichte - Essenziell\nProjizierte Texturen - Aktiviert (für Bodeneffekte nötig)\nSichtweite - Auf 1 reduziert\nUmgebungsdetails - Auf 1 reduziert\nBodenobjekte - Auf 1 reduziert\nSchlachtzug/Dungeon - Verwendet überall dieselben Einstellungen\nNachschärfen - Aktiviert (schärferes Bild)\nKontrast - Um +10 erhöht (falls <= 55)\nHall aktivieren - Deaktiviert (Audiosignale bleiben präzise)\n\nDiese Einstellungen bevorzugen Bildrate und Klarheit gegenüber Umgebungsdetails. Texturen bleiben hochaufgelöst."
L["This feature requires Snap Elements to be enabled"] = "Diese Funktion erfordert, dass 'Elemente einrasten' aktiviert ist."
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Diese Funktion führt kontinuierliche Reichweitenprüfungen für jede sichtbare feindliche Namensplakette durch. Dies ist eine der rechenintensiveren Funktionen in EllesmereUI und kann die CPU-Auslastung in belebten Bereichen spürbar erhöhen."
L["This frame's source changes require a UI reload to take effect."] = "Änderungen an der Quelle dieses Fensters erfordern ein Neuladen des UI."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Der benutzerdefinierte Schwächungszauber-Manager dieser Gruppe kann nur aktiviert oder bearbeitet werden, während eine ihrer Spezialisierungen gespielt wird."
L["this indicator"] = "dieser Indikator"
L["This is a voice preview"] = "Dies ist eine Sprachvorschau"
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "Dies ist die vollständige Überlagerung, die während der Zauberdauer von rechts nach links über das Symbol wischt"
L["This is the spec you're syncing from -- it's always included."] = "Dies ist die Spezialisierung, von der Du synchronisierst – sie ist immer enthalten."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Dies ist das Zauber-Warteschlangenfenster. Es verhindert das Reihen zu vieler Zauber auf einmal, was sich schwammig anfühlen kann. Empfohlen: mindestens 200 + lokaler Ping. Wenn Du unsicher bist, belasse es bei 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Hier steuerst Du die Einstellungen des Freigabemodus.\n\nElemente können durch Ziehen oder Pfeiltasten (+ Umschalt) verschoben werden.\nVerankere, passe Höhe oder Breite an jedes Element an.\nEinrasten basiert auf dem nächsten Element, kann aber per Rechtsklick oder Einstellungssymbol auf ein bestimmtes Element beschränkt werden."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Bewirkt, dass die Breite der Zauberleiste das Symbol beinhaltet, anstatt es links außerhalb der Leistenbreite zu platzieren."
L["This module can't be overridden. Exit the override editing session to open it."] = "Dieses Modul kann nicht überschrieben werden. Beende die Bearbeitungssitzung der Überschreibung, um es zu öffnen."
L["This option allows you to set custom frame sizing and positioning to different raid sizes. Note: This does NOT resize/reposition frames while in combat, if players join/leave mid combat it will resize after combat completes."] = "Erlaubt benutzerdefinierte Fenstergrößen/ Positionen für verschiedene Schlachtzugsgrößen. Hinweis: Passt Fenster NICHT im Kampf an – Änderungen greifen nach Kampfende."
L["This option applies to bar Type resources only (pips use stack counts)."] = "Gilt nur für leistenspezifische Ressourcen (Punkte nutzen Stapelzähler)."
L["This option applies to pip Type resources only."] = "Gilt nur für punktbasierte Ressourcen."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Nicht nutzbar, während 'Ressourcenleiste erweitern, wenn keine Klassenressource vorhanden' aktiviert ist."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Nicht nutzbar, während 'Elemente verschieben, wenn keine Klassenressource vorhanden' aktiviert ist."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Nicht nutzbar, solange die Ressourcenleistenhöhe im Freigabemodus angepasst ist."
L["This option does not apply while Anchor to Cursor is enabled"] = "Gilt nicht, solange 'An Mauszeiger verankern' aktiviert ist"
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "Funktioniert nicht mit Blizzard Leisten. Bitte nutze den Blizzard Bearbeitungsmodus."
L["This option is not available for custom shaped icons"] = "Nicht verfügbar für individuell geformte Symbole"
L["This option is not supported for this bar type"] = "Für diesen Leistentyp nicht unterstützt"
L["This option is now controlled by the Raid Frames addon"] = "Wird jetzt vom Schlachtzugsfenster Addon gesteuert"
L["This option is only available for abilities with multiple charges"] = "Nur verfügbar für Fähigkeiten mit mehreren Aufladungen"
L["This option is only available for formats that display a percentage."] = "Nur verfügbar für Formate, die einen Prozentwert anzeigen."
L["This option is only available for the Custom Color Theme"] = "Nur verfügbar für das benutzerdefinierte Farb Theme"
L["This option is only available when Portrait Mode is Detached."] = "Nur verfügbar, wenn der Porträtmodus auf 'Lösgetrennt' steht."
L["This option is only used by the Basic border."] = "Wird nur vom einfachen Rahmen verwendet."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Betrifft nur Schlachtzug Stärkungszauber und Paladin Flammen"
L["This option requires <text> to be enabled"] = "Erfordert, dass <text> aktiviert ist"
L["This option requires a Border Size above 0."] = "Erfordert eine Rahmengröße über 0."
L["This option requires a Class Icon other than None."] = "Erfordert ein anderes Klassensymbol als 'Keine'."
L["This option requires a cooldown-tracking bar"] = "Erfordert eine Abklingzeiten Verfolgungsleiste"
L["This option requires a custom glow to be selected"] = "Erfordert die Auswahl eines benutzerdefinierten Leuchtens"
L["This option requires a custom thickness to be set."] = "Erfordert die Festlegung einer benutzerdefinierten Dicke."
L["This option requires a detached position to be active."] = "Erfordert eine aktive, lösgetrennte Position."
L["This option requires a dropdown selection other than Above Health Bar"] = "Erfordert eine andere Auswahl im Dropdown Menü als 'Über Gesundheitsleiste'"
L["This option requires a Duration Text position other than None"] = "Erfordert eine andere Dauer Textposition als 'Keine'"
L["This option requires a Glow Type other than None"] = "Erfordert einen anderen Leuchttyp als 'Keiner'"
L["This option requires a gradient to be set"] = "Erfordert die Festlegung eines Farbverlaufs"
L["This option requires a Health Text format other than None"] = "Erfordert ein anderes GesundheitstextFormat als 'Keines'"
L["This option requires a Name Text position other than None"] = "Erfordert eine andere Namenstext Position als 'Keine'"
L["This option requires a non-custom button shape"] = "Erfordert eine nicht-benutzerdefinierte Tastenform"
L["This option requires a non-custom shape to be selected"] = "Erfordert die Auswahl einer nicht-benutzerdefinierten Form"
L["This option requires a non-custom shaped action bar"] = "Erfordert eine Aktionsleiste ohne benutzerdefinierte Form"
L["This option requires a Power Text format other than None"] = "Erfordert ein anderes RessourcentextFormat als 'Keines'"
L["This option requires a Stacks Text position other than None"] = "Erfordert eine andere Stapel Textposition als 'Keine'"
L["This option requires a text position other than none."] = "Erfordert eine andere Textposition als 'Keine'."
L["This option requires a text selection other than none."] = "Erfordert eine andere Textauswahl als 'Keine'."
L["This option requires a text to be assigned"] = "Erfordert die Zuweisung eines Textes"
L["This option requires Add Friendly Boss Group to be set to Healers or Always."] = "Erfordert, dass 'Freundliche Bossgruppe hinzufügen' auf 'Heiler' oder 'Immer' eingestellt ist."
L["This option requires an aura or indicator to be assigned"] = "Erfordert die Zuweisung einer Aura oder eines Indikators"
L["This option requires Blizzard Style Action Bars to be disabled"] = "Erfordert, dass Aktionsleisten im Blizzard Stil deaktiviert sind"
L["This option requires Class Colors to be disabled"] = "Erfordert, dass Klassenfarben deaktiviert sind"
L["This option requires Class Resource to be set to Modern."] = "Erfordert, dass die Klassenressource auf 'Modern' eingestellt ist."
L["This option requires Combine Spell Name and Target to be disabled."] = "Erfordert, dass 'Zaubernamen und Ziel kombinieren' deaktiviert ist."
L["This option requires Display Style to be set to Icon"] = "Erfordert, dass der Anzeigestil auf 'Symbol' eingestellt ist"
L["This option requires Display Style to be set to Text"] = "Erfordert, dass der Anzeigestil auf 'Text' eingestellt ist"
L["This option requires exactly 2 rows"] = "Erfordert exakt 2 Zeilen"
L["This option requires Fill Color to be set to Custom"] = "Erfordert, dass die Füllfarbe auf 'Benutzerdefiniert' eingestellt ist"
L["This option requires Icon Shape to be set to None or Cropped"] = "Erfordert, dass die Symbolform auf 'Keine' oder 'Zugeschnitten' eingestellt ist"
L["This option requires Pixel Glow to be the selected glow type"] = "Erfordert, dass 'Pixel Leuchten' als Leuchttyp ausgewählt ist"
L["This option requires Portrait Mode to be set to Detached."] = "Erfordert, dass der Porträtmodus auf 'Lösgetrennt' eingestellt ist."
L["This option requires Show Tooltips to be set to hide tooltips"] = "Erfordert, dass 'Tooltips anzeigen' so eingestellt ist, dass Tooltips ausgeblendet werden"
L["This option requires Subtitle Text to include the Guild Name"] = "Erfordert, dass der Untertiteltext den Gildennamen enthält"
L["This option requires the Border Style to be set to Solid"] = "Erfordert, dass der Rahmenstil auf 'Einfarbig' eingestellt ist"
L["This option requires the module to be enabled"] = "Erfordert, dass das Modul aktiviert ist"
L["This option requires the position setting to be detached"] = "Erfordert, dass die Positionseinstellung lösgetrennt ist"
L["This option requires Threshold Settings to be disabled"] = "Erfordert, dass Schwellenwert Einstellungen deaktiviert sind"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Diese Überschreibung besitzt keine Indikatoren für diese Spezialisierung, daher wird hier nichts angezeigt, bis Du welche hinzufügst."
L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Überschreibt die aktuellen Einstellungen dieses Aktionsmenüs. Aktionen, Name und Tastenbelegung bleiben unverändert."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Überschreibt die aktuellen Einstellungen dieses Fensters. Position, Sichtbarkeit und Aktivierungszustand bleiben unverändert."
L["This page is excluded from overrides."] = "Diese Seite ist von Überschreibungen ausgeschlossen."
L["This preset"] = "Diese Voreinstellung"
L["This profile already holds 16 action menus"] = "Dieses Profil enthält bereits 16 Aktionsmenüs"
L["This profile string does not carry any override data."] = "Dieser Profilstring enthält keine Überschreibungsdaten."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Dieser Profil-String enthält keine Einstellungen für Fenster- & Tooltip Skins."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Profil wurde bei %1$d%% UI Skalierung erstellt; Deine ist %2$d%%. UI Skalierung anpassen? Gilt profilübergreifend, kann aber jederzeit zurückgesetzt werden."
L["This replaces %d existing value(s) for this setting across your specs."] = "Ersetzt %d bestehende(n) Wert(e) für diese Einstellung über Deine Spezialisierungen hinweg."
L["This replaces %d existing value(s) for this setting on this bar."] = "Ersetzt %d bestehende(n) Wert(e) für diese Einstellung auf dieser Leiste."
L["This resets every EUI addon, not just the current one."] = "Setzt jedes EUI Addon zurück, nicht nur das aktuelle."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "Der aktive Wert für 'Auf Leiste anwenden (Alle Spezialisierungen)' dieser Einstellung wird ersetzt."
L["This setting's active Apply to Bar value will be replaced."] = "Der aktive Wert für 'Auf Leiste anwenden' dieser Einstellung wird ersetzt."
L["This spec doesn't have this spell."] = "Diese Spezialisierung besitzt diesen Zauber nicht."
L["this spec"] = "diese Spezialisierung"
L["This spell is already being used on %s"] = "Dieser Zauber wird bereits auf %s verwendet"
L["This spell"] = "Dieser Zauber"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Dies ist ein VOLLSTÄNDIGER ACCOUNT-Export. Er ersetzt Deine accountweiten Einstellungen (Komfortfunktionen, HoverCast, CDM-Setup, Anker, UI Skalierung etc.) durch die des Absenders. Andere Profile bleiben erhalten; gleichnamige werden ersetzt."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Diese Einheit nutzt das Blizzard-Standardfenster – hier gibt es keine EllesmereUI Einstellungen."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Das Fenster dieser Einheit ist ausgeblendet – hier gibt es keine EllesmereUI Einstellungen."
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Ändert die Farbe Deiner Leiste, wenn Du mehr als die gewählte Anzahl an Stapeln hast"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber-Manager für diese bedingte Gruppe. Änderungen an Deinem Standard Stärkungszauber Manager wirken sich nicht mehr darauf aus."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber-Manager für diese Überschreibungsgruppe. Änderungen an Deinem Standard Stärkungszauber Manager wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Schwächungszauber Manager für diese bedingte Gruppe. Aktuelle Einstellungen werden kopiert; spätere Änderungen am Standard betreffen diese Gruppe nicht mehr."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Schwächungszauber Manager für diese Überschreibungsgruppe. Aktuelle Einstellungen werden kopiert; spätere Änderungen am Standard betreffen diese Spezialisierungen nicht mehr."
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "Deaktiviert EllesmereUI Statusleisten und zeigt stattdessen Blizzards Standardanzeige."
L["This will discard your custom party settings for this section and use raid settings instead."] = "Verwirft Deine eigenen Gruppeneinstellungen für diesen Abschnitt und nutzt stattdessen die Schlachtzugseinstellungen."
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Zeigt das Wort 'FOKUS' unter Zauberer-/Miniboss Gegnern in M+ an, wenn Du kein Fokusziel gesetzt hast. Deaktiviert für Spezialisierungen ohne Unterbrechungszauber."
L["This will keep appearing each login until the layout is correct."] = "Wird bei jedem Login erneut erscheinen, bis das Layout korrekt ist."
L["This will not override sorting by role"] = "Überschreibt nicht die Sortierung nach Rolle"
L["This will not reset addon-specific Quick Setup."] = "Setzt die addon spezifische Schnelleinrichtung nicht zurück."
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Verteilt Gegenstände physisch an zufällige Positionen in Deinen Taschen. Änderungen bleiben auch bei Deaktivierung von EllesmereUI Bags bestehen."
L["This will pin your bar to the window when it is not within the visible area"] = "Heftet Deine Leiste an das Fenster an, wenn sie sich nicht im sichtbaren Bereich befindet"
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Ersetzt DEINE Einstellungen für die erweiterte Blizzard UI (Skins, Tooltips, Menüs & Popups) über ALLE Profile hinweg durch die des Absenders. Aktuelle Einstellungen gehen verloren."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Setzt alle Standard Leistenzuweisungen der aktuellen Spezialisierung auf das Blizzard CDM Layout zurück. Eigene Zauber bleiben erhalten. Fortfahren?"
L["This will reset all saved panel positions and zoom levels and reload your UI."] = "Setzt alle gespeicherten Fensterpositionen und Zoomstufen zurück und lädt das UI neu."
