L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Färbt einen Eintrag ein, der aktuell nicht nutzbar ist: Rot bei außer Reichweite, Blau bei Ressourcenmangel, Grau aus sonstigen Gründen. Nur für Zauber und Gegenstände."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Färbt die Zauberleiste mit der 'Wichtig' Farbe ein, wenn der Gegner einen als wichtig markierten Zauber wirkt. Überschreibt die 'Unterbrechbar' Farbe; eine eigene Abklingzeit hat weiterhin Vorrang."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Färbt die Zauberleiste mit der 'Wichtig' Farbe ein, wenn die Einheit einen als wichtig markierten Zauber wirkt. Eine eigene Abklingzeit auf der Unterbrechung hat weiterhin Vorrang."
L["Tint the combat icon by the member's class color. Not available for the Arcade/Dungeoneer/Classic/Cross/Circle/Square styles."] = "Färbt das Kampfsymbol in der Klassenfarbe des Mitglieds ein. Nicht verfügbar für die Stile Arcade, Dungeoneer, Klassisch, Kreuz, Kreis und Quadrat."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Färbt das Muster mit der aktuellen Farbe der Leiste statt mit der benutzerdefinierten Überlagerungsfarbe ein."
L["Tints this block's slot with its own color."] = "Färbt den Platz dieses Blocks mit seiner eigenen Farbe ein."
