L["Toggles Blizzard's Show Numbers for Cooldowns setting, which will show number text on any spells that are on cooldown on your action bars."] = "Schaltet Blizzards Einstellung 'Zahlen für Abklingzeiten anzeigen' um, die Zahlen auf zaubernden Aktionsleisten Tasten anzeigt."
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Schaltet die Schlachtzugswerkzeuge Fenster im oder außerhalb des Kampfes um.\n\nLinksklick zum Festlegen einer Tastenbelegung.\nRechtsklick zum Aufheben."
