L["When Any Present"] = "Wenn irgendeiner vorhanden"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Wenn deaktiviert, überlässt EUI die vollständige Kontrolle über die Namensplaketten freundlicher Spieler Blizzard. Nutze Blizzards eigene Namensplaketten Einstellungen (Esc > Optionen > Namensplaketten), um sie zu steuern."
L["When Dragonriding"] = "Beim Himmelsreiten"
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Wenn aktiviert, zeigen BM- und MM-Spezialisierungen Fokus als standardmäßige Ressourcenleiste anstelle einer Klassenressourcen Leiste an."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Wenn aktiviert, speichert das Ziehen eines Fensters mit der linken Maustaste dessen Position, ohne dass Umschalt gehalten werden muss. Strg+Ziehen führt weiterhin ein vorübergehendes Verschieben aus."
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Wenn aktiviert, verschiebt das Ziehen des Taschenfensters mit der linken Maustaste dieses, ohne dass Umschalt gehalten werden muss."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Wenn aktiviert, nutze Umschalt+Klick auf eine beliebige Minikartentaste (Post, Kalender, Verfolgung, Addon Tasten), um sie an eine eigene Position zu ziehen. Beim Ziehen rasten Tasten an nahegelegenen Tasten und am Minikartenrand ein; halte Strg zusammen mit Umschalt gedrückt, um das Einrasten zu deaktivieren."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Wenn aktiviert, nutze Umschalt+Klick auf eine beliebige Minimap Taste (Post, Kalender, Verfolgung, Addon Tasten), um sie an eine eigene Position zu ziehen."
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Wenn aktiviert, nutze Umschalt+Klick auf ein beliebiges Seitenleisten Symbol, um es an eine eigene Position zu ziehen."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Wenn aktiviert, werden die Zusatztasten (Schatzkammer, M+ Portale, Freunde online, Gruppentaste) und alle nicht gruppierten Minikartentasten nur angezeigt, während sich die Maus über der Minikarte befindet. Das M+ Portale Menü hält sie sichtbar, bis es schließt."
L["When hovering any action bar set to Mouseover, all Mouseover bars will appear."] = "Beim Drüberbewegen über eine beliebige Aktionsleiste, die auf Mouseover eingestellt ist, werden alle Mouseover Leisten angezeigt."
L["When Not Dragonriding"] = "Außerhalb des Himmelsreitens"
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Wenn aktiviert, werden Fläschchen-/Essen-/Waffenerinnerungen weiterhin (abgedunkelt) angezeigt, wenn Du keinen passenden Gegenstand in den Taschen hast, als Aufforderung zum Aufstocken.\nWenn deaktiviert, werden sie vollständig ausgeblendet, wenn Du den Gegenstand nicht bei Dir führst."
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Wenn die Klassenressourcen Leiste nicht angezeigt wird, fügt dies automatisch die Höhe der Klassenressource zur Ressourcenleiste hinzu."
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Wenn die aktuelle Spezialisierung keine Leisten in dieser Gruppe hat, hält dies an der Gruppe verankerte Elemente an Ort und Stelle und verschiebt sie um eine Leistenhöhe nach oben oder unten (anpassbar mit dem 'Zusätzlichen Y-Versatz' im Zahnrad), um deren leeren Platz abzudecken."
L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Zählt bei der Verwendung eigener Schlachtzugsgrößen Mitglieder in ausgeblendeten Gruppen nicht für den Schwellenwert der Schlachtzugsgröße mit. Wenn Du beispielsweise Gruppe 7 und 8 ausblendest, wird ein voller 40-Spieler Schlachtzug so skaliert, als wäre er für 24 Spieler ausgelegt, anstatt auf die Fenstergröße für 30 Spieler zu springen. Hat keine Wirkung, außer wenn eigene Schlachtzugsgrößen eingerichtet sind."
L["When you are solo, center the player frame on the party frame instead of anchoring it at the top."] = "Zentriert das Spielerfenster auf dem Gruppenfenster, wenn Du solo bist, anstatt es oben zu verankern."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Wenn Du einer Gruppe im Dungeongefinder für einen Dungeon mit Teleport beitrittst, wird ein kleines verschiebbares Popup mit dem Dungeon-Namen und einer Ein-Klick-Teleporttaste angezeigt. Es wird ausgeblendet, sobald Du den Dungeon betrittst, die Gruppe verlässt oder den Kampf betrittst."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Zeigt beim Drücken der Tastenbelegung einer Fähigkeit die 'Gedrückt'-Optik der Aktionstaste auf deren Symbol auf dieser Leiste an – selbst wenn sich die Fähigkeit auf Abklingzeit befindet."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Wenn Du während einer Cinematic-Sequenz Escape oder Leertaste drückst, wird die Bestätigungsabfrage automatisch akzeptiert."
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "Wenn Du keine Kampf-Tränke eines bestimmten Typs mehr in den Taschen hast, wechselt das Symbol zur Verfolgung des nächsten Typs in Deinem Besitz."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Wenn Du keine Tränke eines bestimmten Typs mehr in den Taschen hast, wechselt das Symbol zur Verfolgung des anderen Typs."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Wenn Dein Unterbrechungszauber aktuell auf Abklingzeit ist, aber bereit sein wird, bevor der gegnerische Zauber endet, wird der Teil der Zauberleiste eingefärbt, in dem Dein Unterbrechungszauber verfügbar sein wird. Die Farbe verschwindet in dem Moment, in dem Dein Unterbrechungszauber bereit wird."
L["Whenever not airborne on a skyriding mount."] = "Wann immer nicht in der Luft auf einem Himmelsreiten Reittier."
L["Where the block's content sits inside its slot."] = "Wo der Inhalt des Blocks innerhalb seines Platzes sitzt."
L["Where the icon strip sits inside its slot."] = "Wo die Symbolleiste innerhalb ihres Platzes sitzt."
L["Where to Show"] = "Wo anzeigen"
L["Which audio channel the block's volume bar adjusts."] = "Welchen Audiokanal die Lautstärkeleiste des Blocks anpasst."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "Welchen Ruhestein der Linksklick nutzt. 'Zufälliger Ruhestein' wählt bei jedem Wirken eine zufällige Variante in Deinem Besitz. Rechtsklick wählt immer einen zufälligen aus."
L["Which latency to show: home, world, or both side by side."] = "Welche Latenz angezeigt werden soll: Standort, Welt oder beide nebeneinander."
L["Which micro menu buttons this block shows."] = "Welche Mikromenütasten dieser Block anzeigt."
L["Which minimap corner the Blizzard element row (tracking, calendar, mail, crafting) builds out from and the direction it grows."] = "Von welcher Minikarten Ecke die Blizzard Elementzeile (Verfolgung, Kalender, Post, Handwerk) ausgeht und in welche Richtung sie wächst."
L["Which minimap corner the button row builds out from and the direction it grows."] = "Von welcher Minikartenecke die Tastenzeile ausgeht und in welche Richtung sie wächst."
L["Which sections the gold tooltip shows."] = "Welche Abschnitte der Gold Tooltip anzeigt."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "In welcher Ansicht Taschen (und die Bank) standardmäßig geöffnet werden. Die Bank hat keine MultiBag Ansicht, daher öffnet Mehrfachtasche die Bank in Einzeltasche."
L["Which way new bars stack as more enemies start casting."] = "In welche Richtung sich neue Leisten stapeln, wenn weitere Gegner zu zaubern beginnen."
L["Which way the rows stack as healers are added."] = "In welche Richtung sich die Zeilen stapeln, wenn Heiler hinzugefügt werden."
L["Which way the windows extend from the collapsed icon when they open."] = "In welche Richtung sich die Fenster beim Öffnen vom eingeklappten Symbol aus ausdehnen."
L["While dragging a spell or item, this bar appears so you can drop onto it."] = "Beim Ziehen eines Zaubers oder Gegenstands erscheint diese Leiste, damit Du ihn darauf ablegen kannst."
L["While the spellbook or macro panel is open, this bar appears so you can drag abilities onto it."] = "Solange das Zauberbuch oder das Makrofenster geöffnet ist, erscheint diese Leiste, damit Du Fähigkeiten darauf ziehen kannst."
