L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Deine aktuelle Spezialisierung besitzt ihren eigenen Freigabemodus, daher finden bedingte Freigabemodi niemals Anwendung auf sie. Wechsle zu einer Spezialisierung ohne eigenen Freigabemodus, um dies anzupassen."
